/* Collection pages share the notebook's title, description, actions and content rhythm. */
v2ThinkingMatrix=()=>'';
const notebook7=notebook;notebook=()=>notebook7().replace('notebook-spread v3-notebook','notebook-spread v3-notebook collection-page').replace('<header>','<header class="collection-head">');
const bookAuthor7={hidden:'Jasper Kim',carter:'Lee Hartley Carter'};
function sourceCard7(key,source){const book=PINA_BOOK_COVERS[key];return `<section class="source-card ${book?'has-cover':''}">${book?`<a class="book-cover" href="${esc(book.url)}" target="_blank" rel="noopener noreferrer" aria-label="View ${esc(source.name)}"><img src="${book.image}" alt="Cover of ${esc(source.name)}" width="112" height="164" loading="lazy"></a>`:''}<div><h3>${esc(source.name)}</h3><p>${esc(bookAuthor7[key]||source.author)}</p>${book?`<a class="text-link" href="${esc(book.url)}" target="_blank" rel="noopener noreferrer">Book details ↗</a>`:''}</div></section>`;}
shelf=()=>shell(`<section class="v2-shelf collection-page"><a class="back-link collection-back" href="#home">← Back to the toolkit</a><header class="collection-head"><h1>The research shelf</h1><p>The source mapping follows your supplied course reading list. The combinations here are practical reflection prompts.</p><div class="notebook-actions"><a class="ink-button primary" href="#casebook">Open the Netflix casebook ${ic('arrow')}</a></div></header><div class="v2-shelf-tools">${Object.entries(V2.tools).map(([id,t])=>`<details><summary>${esc(t.name)}</summary><p>${esc(t.reading)}</p>${v2SourceTags(Number(id))}<a class="text-link" href="${v2LearnHref(Number(id))}">Explore the idea →</a></details>`).join('')}</div><h2>Course books</h2><div class="v2-bibliography book-bibliography">${Object.entries(V2.sources).filter(([key])=>PINA_BOOK_COVERS[key]).map(([key,source])=>sourceCard7(key,source)).join('')}</div><h2>Lectures and other sources</h2><div class="v2-bibliography other-bibliography">${Object.entries(V2.sources).filter(([key])=>!PINA_BOOK_COVERS[key]).map(([key,source])=>sourceCard7(key,source)).join('')}</div><p class="v3-disclaimer">These tools are practical interpretations of the supplied readings. Check the original sources before academic citation.</p></section>`,'shelf-page v2-page');
casebook=()=>shell(`<section class="v3-case-index collection-page"><header class="collection-head"><p class="eyebrow">NETFLIX CASEBOOK</p><h1>Stories in context</h1><p>See how the tools reveal different readings of the same Netflix decision or message.</p><div class="notebook-actions"><a class="ink-button primary" href="#shelf">Back to research ${ic('arrow')}</a></div></header><div class="casebook-cards">${CASES.map(c=>`<article><p class="eyebrow">${esc(c.label)}</p><h2>${esc(c.title)}</h2><div class="casebook-tool-links">${c.tools.map(id=>`<a class="text-link" href="${v2CaseHref(id)}">${esc(v2Tool(id).name)} ${ic('arrow')}</a>`).join('')}</div></article>`).join('')}</div></section>`,'chapter-page');
route();
